// Een laag als lijst vormen in graden: { naam, breedte, ll: [[lat, lon], ...] }. De tekenaar
// rekent dat met de eigen toXZ om, zodat de kaart dezelfde projectie volgt als de rest.
const cache = new Map();
export function laag(icao, sleutel) {
  const k = icao + '/' + sleutel;
  if (cache.has(k)) return cache.get(k);
  const v = GRONDKAART[icao];
  const uit = [];
  for (const vorm of (v && v[sleutel]) || []) {
    const ll = [];
    let x = vorm[2], y = vorm[3];
    const kx = 111320 * Math.cos(v.lat * Math.PI / 180), ky = 110574;
    ll.push([v.lat + y / ky, v.lon + x / kx]);
    for (let i = 4; i < vorm.length; i += 2) {
      x += vorm[i]; y += vorm[i + 1];
      ll.push([v.lat + y / ky, v.lon + x / kx]);
    }
    uit.push({ naam: vorm[0], breedte: vorm[1], ll });
  }
  cache.set(k, uit);
  return uit;
}

export const VELDEN = Object.keys(GRONDKAART);
export function heeftKaart(icao) { return !!GRONDKAART[icao]; }
